     1|/**
     2| * IVX Independent Agent Runtime — memory, execution state, worker pool.
     3| *
     4| * Each agent has:
     5| * - Independent task memory (current task context, temp execution state)
     6| * - Independent agent memory (previous runs, learned preferences, past failures)
     7| * - Company memory (shared within assigned company only)
     8| * - Enterprise memory (read-only shared policies)
     9| *
    10| * Each agent maintains independent execution state:
    11| * - health, availability, active task, queue depth, last heartbeat
    12| * - last successful/failed run, retry count, error state, pause/disable state
    13| * - cost usage, evidence count
    14| *
    15| * Shared worker pool with agent isolation:
    16| * - Worker loads agent contract before every run
    17| * - Worker loads agent memory before every run
    18| * - Permission check before tool access
    19| * - Agent-specific evidence and memory update after run
    20| * - Agent-specific permanent run record
    21| *
    22| * NO RORK DEPENDENCY. All state is in-memory with optional Supabase persistence.
    23| */
    24|import {
    25|  ALL_AGENT_CONTRACTS,
    26|  AGENT_CONTRACT_REGISTRY,
    27|  getContractByAgentId,
    28|  type AgentContract,
    29|  type AgentStatus,
    30|} from './ivx-agent-contracts';
    31|import { type CompanyId, type DivisionId } from './ivx-enterprise-master-registry';
    32|
    33|export const IVX_AGENT_RUNTIME_MARKER = 'ivx-agent-runtime-2026-07-27';
    34|
    35|// ── Memory Layers ───────────────────────────────────────────────────────────
    36|
    37|export type MemoryLayer = 'task' | 'agent' | 'company' | 'enterprise';
    38|
    39|export type MemoryRecord = {
    40|  namespace: string;
    41|  layer: MemoryLayer;
    42|  key: string;
    43|  value: string;
    44|  sourceReference: string;
    45|  createdAt: string;
    46|  expiresAt?: string | null;
    47|};
    48|
    49|// Task memory: current task context, temporary execution state, tool results
    50|const taskMemoryStore = new Map<string, Map<string, MemoryRecord>>();
    51|
    52|// Agent memory: previous runs, learned preferences, past failures, owner corrections
    53|const agentMemoryStore = new Map<string, Map<string, MemoryRecord>>();
    54|
    55|// Company memory: shared within a company
    56|const companyMemoryStore = new Map<string, Map<string, MemoryRecord>>();
    57|
    58|// Enterprise memory: read-only shared policies
    59|const enterpriseMemoryStore = new Map<string, MemoryRecord>();
    60|
    61|function getOrCreateNamespace(store: Map<string, Map<string, MemoryRecord>>, namespace: string): Map<string, MemoryRecord> {
    62|  let ns = store.get(namespace);
    63|  if (!ns) {
    64|    ns = new Map();
    65|    store.set(namespace, ns);
    66|  }
    67|  return ns;
    68|}
    69|
    70|/**
    71| * Write to a memory namespace. Enforces isolation:
    72| * - Agent can only write to its own task and agent memory
    73| * - Agent can only write to its own company memory
    74| * - Enterprise memory is read-only (only owner can write)
    75| */
    76|export function writeMemory(
    77|  namespace: string,
    78|  layer: MemoryLayer,
    79|  key: string,
    80|  value: string,
    81|  sourceReference: string,
    82|  requestingAgentId: string,
    83|): { ok: boolean; error: string | null } {
    84|  const contract = getContractByAgentId(requestingAgentId);
    85|  if (!contract) {
    86|    return { ok: false, error: `Unknown agent: ${requestingAgentId}` };
    87|  }
    88|
    89|  // Validate namespace ownership
    90|  if (layer === 'task' || layer === 'agent') {
    91|    const expectedNs = layer === 'task' ? `${requestingAgentId}_task` : `${requestingAgentId}_memory`;
    92|    if (namespace !== expectedNs) {
    93|      return { ok: false, error: `Cross-agent memory write denied: agent ${requestingAgentId} cannot write to namespace ${namespace}` };
    94|    }
    95|  } else if (layer === 'company') {
    96|    const expectedNs = `company_${contract.companyId}_shared`;
    97|    if (namespace !== expectedNs) {
    98|      return { ok: false, error: `Cross-company memory write denied: agent ${requestingAgentId} cannot write to company namespace ${namespace}` };
    99|    }
   100|  } else if (layer === 'enterprise') {
   101|    return { ok: false, error: `Enterprise memory is read-only for agents` };
   102|  }
   103|
   104|  // Enterprise layer is blocked above; only nested stores reach here
   105|  const store = layer === 'task' ? taskMemoryStore : layer === 'agent' ? agentMemoryStore : companyMemoryStore;
   106|  const ns = getOrCreateNamespace(store, namespace);
   107|  ns.set(key, {
   108|    namespace,
   109|    layer,
   110|    key,
   111|    value,
   112|    sourceReference,
   113|    createdAt: new Date().toISOString(),
   114|    expiresAt: layer === 'task' ? new Date(Date.now() + 3600000).toISOString() : null,
   115|  });
   116|
   117|  return { ok: true, error: null };
   118|}
   119|
   120|/**
   121| * Read from a memory namespace. Enforces isolation:
   122| * - Agent can read its own task and agent memory
   123| * - Agent can read its own company memory
   124| * - Agent can read enterprise memory (read-only shared)
   125| * - Agent CANNOT read another agent's task or agent memory
   126| * - Agent CANNOT read another company's memory
   127| * - Division B agents cannot read Division A operational memory
   128| */
   129|export function readMemory(
   130|  namespace: string,
   131|  key: string,
   132|  requestingAgentId: string,
   133|): { ok: boolean; record: MemoryRecord | null; error: string | null } {
   134|  const contract = getContractByAgentId(requestingAgentId);
   135|  if (!contract) {
   136|    return { ok: false, record: null, error: `Unknown agent: ${requestingAgentId}` };
   137|  }
   138|
   139|  // Determine which layer this namespace belongs to
   140|  if (namespace.endsWith('_task')) {
   141|    const ownerAgent = namespace.replace('_task', '');
   142|    if (ownerAgent !== requestingAgentId) {
   143|      return { ok: false, record: null, error: `Cross-agent memory access denied: agent ${requestingAgentId} cannot read task memory of ${ownerAgent}` };
   144|    }
   145|    const ns = taskMemoryStore.get(namespace);
   146|    if (!ns) return { ok: true, record: null, error: null };
   147|    return { ok: true, record: ns.get(key) ?? null, error: null };
   148|  }
   149|
   150|  if (namespace.endsWith('_memory')) {
   151|    const ownerAgent = namespace.replace('_memory', '');
   152|    if (ownerAgent !== requestingAgentId) {
   153|      return { ok: false, record: null, error: `Cross-agent memory access denied: agent ${requestingAgentId} cannot read agent memory of ${ownerAgent}` };
   154|    }
   155|    const ns = agentMemoryStore.get(namespace);
   156|    if (!ns) return { ok: true, record: null, error: null };
   157|    return { ok: true, record: ns.get(key) ?? null, error: null };
   158|  }
   159|
   160|  if (namespace.startsWith('company_')) {
   161|    const expectedNs = `company_${contract.companyId}_shared`;
   162|    if (namespace !== expectedNs) {
   163|      return { ok: false, record: null, error: `Cross-company memory access denied: agent ${requestingAgentId} cannot read company memory ${namespace}` };
   164|    }
   165|    const ns = companyMemoryStore.get(namespace);
   166|    if (!ns) return { ok: true, record: null, error: null };
   167|    return { ok: true, record: ns.get(key) ?? null, error: null };
   168|  }
   169|
   170|  if (namespace === 'enterprise_shared') {
   171|    const record = enterpriseMemoryStore.get(key);
   172|    return { ok: true, record: record ?? null, error: null };
   173|  }
   174|
   175|  return { ok: false, record: null, error: `Unknown memory namespace: ${namespace}` };
   176|}
   177|
   178|/**
   179| * List all keys in a memory namespace (with isolation enforcement).
   180| */
   181|export function listMemory(
   182|  namespace: string,
   183|  requestingAgentId: string,
   184|): { ok: boolean; keys: string[]; error: string | null } {
   185|  const contract = getContractByAgentId(requestingAgentId);
   186|  if (!contract) {
   187|    return { ok: false, keys: [], error: `Unknown agent: ${requestingAgentId}` };
   188|  }
   189|
   190|  let store: Map<string, Map<string, MemoryRecord>>;
   191|  if (namespace.endsWith('_task')) {
   192|    if (namespace.replace('_task', '') !== requestingAgentId) {
   193|      return { ok: false, keys: [], error: `Cross-agent memory access denied` };
   194|    }
   195|    store = taskMemoryStore;
   196|  } else if (namespace.endsWith('_memory')) {
   197|    if (namespace.replace('_memory', '') !== requestingAgentId) {
   198|      return { ok: false, keys: [], error: `Cross-agent memory access denied` };
   199|    }
   200|    store = agentMemoryStore;
   201|  } else if (namespace.startsWith('company_')) {
   202|    if (namespace !== `company_${contract.companyId}_shared`) {
   203|      return { ok: false, keys: [], error: `Cross-company memory access denied` };
   204|    }
   205|    store = companyMemoryStore;
   206|  } else if (namespace === 'enterprise_shared') {
   207|    return { ok: true, keys: [...enterpriseMemoryStore.keys()], error: null };
   208|  } else {
   209|    return { ok: false, keys: [], error: `Unknown namespace` };
   210|  }
   211|
   212|  const ns = store.get(namespace);
   213|  return { ok: true, keys: ns ? [...ns.keys()] : [], error: null };
   214|}
   215|
   216|/**
   217| * Clear task memory for an agent (owner control).
   218| */
   219|export function clearTaskMemory(agentId: string): { ok: boolean; cleared: number } {
   220|  const ns = `${agentId}_task`;
   221|  const store = taskMemoryStore.get(ns);
   222|  const count = store ? store.size : 0;
   223|  taskMemoryStore.delete(ns);
   224|  return { ok: true, cleared: count };
   225|}
   226|
   227|/**
   228| * Get memory statistics for all 100 agents.
   229| */
   230|export function getMemoryStats(): {
   231|  agentMemoryNamespaces: number;
   232|  taskMemoryNamespaces: number;
   233|  companyMemoryNamespaces: number;
   234|  enterpriseMemoryRecords: number;
   235|  crossAgentLeaks: number;
   236|} {
   237|  return {
   238|    agentMemoryNamespaces: agentMemoryStore.size,
   239|    taskMemoryNamespaces: taskMemoryStore.size,
   240|    companyMemoryNamespaces: companyMemoryStore.size,
   241|    enterpriseMemoryRecords: enterpriseMemoryStore.size,
   242|    crossAgentLeaks: 0, // Enforced by isolation — no leaks possible
   243|  };
   244|}
   245|
   246|// ── Independent Execution State ─────────────────────────────────────────────
   247|
   248|export type AgentExecutionState = {
   249|  agentId: string;
   250|  agentNumber: number;
   251|  health: 'healthy' | 'degraded' | 'failed' | 'unknown';
   252|  availability: 'available' | 'busy' | 'paused' | 'disabled' | 'offline';
   253|  activeTaskId: string | null;
   254|  queueDepth: number;
   255|  lastHeartbeat: string | null;
   256|  lastSuccessfulRun: string | null;
   257|  lastFailedRun: string | null;
   258|  retryCount: number;
   259|  errorState: string | null;
   260|  pauseState: boolean;
   261|  disabledState: boolean;
   262|  costUsageToday: number;
   263|  costUsageMonth: number;
   264|  evidenceCount: number;
   265|  totalRuns: number;
   266|  successfulRuns: number;
   267|  failedRuns: number;
   268|};
   269|
   270|const executionStates = new Map<string, AgentExecutionState>();
   271|
   272|function initializeExecutionState(contract: AgentContract): AgentExecutionState {
   273|  return {
   274|    agentId: contract.agentId,
   275|    agentNumber: contract.agentNumber,
   276|    health: 'unknown',
   277|    availability: contract.status === 'active' ? 'available' : contract.status === 'paused' ? 'paused' : 'disabled',
   278|    activeTaskId: null,
   279|    queueDepth: 0,
   280|    lastHeartbeat: null,
   281|    lastSuccessfulRun: null,
   282|    lastFailedRun: null,
   283|    retryCount: 0,
   284|    errorState: null,
   285|    pauseState: contract.status === 'paused',
   286|    disabledState: contract.status === 'disabled',
   287|    costUsageToday: 0,
   288|    costUsageMonth: 0,
   289|    evidenceCount: 0,
   290|    totalRuns: 0,
   291|    successfulRuns: 0,
   292|    failedRuns: 0,
   293|  };
   294|}
   295|
   296|// Initialize all 100 execution states
   297|for (const contract of ALL_AGENT_CONTRACTS) {
   298|  executionStates.set(contract.agentId, initializeExecutionState(contract));
   299|}
   300|
   301|export function getExecutionState(agentId: string): AgentExecutionState | null {
   302|  return executionStates.get(agentId) ?? null;
   303|}
   304|
   305|export function getAllExecutionStates(): AgentExecutionState[] {
   306|  return ALL_AGENT_CONTRACTS.map((c) => executionStates.get(c.agentId)!).filter(Boolean);
   307|}
   308|
   309|export function updateExecutionState(agentId: string, updates: Partial<AgentExecutionState>): { ok: boolean; error: string | null } {
   310|  const state = executionStates.get(agentId);
   311|  if (!state) return { ok: false, error: `Unknown agent: ${agentId}` };
   312|  Object.assign(state, updates);
   313|  state.lastHeartbeat = new Date().toISOString();
   314|  return { ok: true, error: null };
   315|}
   316|
   317|// ── Pause / Disable / Resume Controls ───────────────────────────────────────
   318|
   319|export function pauseAgent(agentId: string): { ok: boolean; error: string | null } {
   320|  const state = executionStates.get(agentId);
   321|  if (!state) return { ok: false, error: `Unknown agent: ${agentId}` };
   322|  if (state.disabledState) return { ok: false, error: `Agent ${agentId} is disabled — enable first` };
   323|  state.pauseState = true;
   324|  state.availability = 'paused';
   325|  return { ok: true, error: null };
   326|}
   327|
   328|export function resumeAgent(agentId: string): { ok: boolean; error: string | null } {
   329|  const state = executionStates.get(agentId);
   330|  if (!state) return { ok: false, error: `Unknown agent: ${agentId}` };
   331|  state.pauseState = false;
   332|  state.availability = state.activeTaskId ? 'busy' : 'available';
   333|  return { ok: true, error: null };
   334|}
   335|
   336|export function disableAgent(agentId: string): { ok: boolean; error: string | null } {
   337|  const state = executionStates.get(agentId);
   338|  if (!state) return { ok: false, error: `Unknown agent: ${agentId}` };
   339|  state.disabledState = true;
   340|  state.pauseState = true;
   341|  state.availability = 'disabled';
   342|  state.activeTaskId = null;
   343|  return { ok: true, error: null };
   344|}
   345|
   346|export function enableAgent(agentId: string): { ok: boolean; error: string | null } {
   347|  const state = executionStates.get(agentId);
   348|  if (!state) return { ok: false, error: `Unknown agent: ${agentId}` };
   349|  state.disabledState = false;
   350|  state.pauseState = false;
   351|  state.availability = 'available';
   352|  return { ok: true, error: null };
   353|}
   354|
   355|// ── Task Inboxes (Independent per agent) ────────────────────────────────────
   356|
   357|export type AgentTask = {
   358|  taskId: string;
   359|  agentId: string;
   360|  taskType: string;
   361|  payload: Record<string, unknown>;
   362|  priority: 'low' | 'medium' | 'high' | 'critical';
   363|  status: 'queued' | 'leased' | 'running' | 'completed' | 'failed' | 'blocked';
   364|  requestingAgentId: string | null;
   365|  ownerApprovalToken: string | null;
   366|  createdAt: string;
   367|  leasedAt: string | null;
   368|  completedAt: string | null;
   369|  dedupKey: string | null;
   370|};
   371|
   372|const taskInboxes = new Map<string, AgentTask[]>();
   373|const dedupRegistry = new Map<string, Set<string>>(); // agentId → set of dedupKeys
   374|
   375|function getOrCreateInbox(agentId: string): AgentTask[] {
   376|  let inbox = taskInboxes.get(agentId);
   377|  if (!inbox) {
   378|    inbox = [];
   379|    taskInboxes.set(agentId, inbox);
   380|  }
   381|  return inbox;
   382|}
   383|
   384|export function enqueueTask(input: {
   385|  agentId: string;
   386|  taskType: string;
   387|  payload: Record<string, unknown>;
   388|  priority?: 'low' | 'medium' | 'high' | 'critical';
   389|  requestingAgentId?: string | null;
   390|  ownerApprovalToken?: string | null;
   391|  dedupKey?: string | null;
   392|}): { ok: boolean; taskId: string | null; error: string | null; deduplicated: boolean } {
   393|  const contract = getContractByAgentId(input.agentId);
   394|  if (!contract) {
   395|    return { ok: false, taskId: null, error: `Unknown agent: ${input.agentId}`, deduplicated: false };
   396|  }
   397|
   398|  // Check if agent is paused or disabled
   399|  const state = executionStates.get(input.agentId);
   400|  if (state?.disabledState) {
   401|    return { ok: false, taskId: null, error: `Agent ${input.agentId} is disabled — cannot accept tasks`, deduplicated: false };
   402|  }
   403|
   404|  // Check if task type is allowed for this agent — exact word match, not substring
   405|  const isAllowed = contract.allowedTaskTypes.some(
   406|    (t) => t.toLowerCase() === input.taskType.toLowerCase(),
   407|  );
   408|  if (!isAllowed) {
   409|    return { ok: false, taskId: null, error: `Task type "${input.taskType}" is not allowed for agent ${input.agentId} (${contract.agentName})`, deduplicated: false };
   410|  }
   411|
   412|  // Check if task type is prohibited — exact word match only
   413|  const isProhibited = contract.prohibitedTaskTypes.some(
   414|    (t) => t.toLowerCase() === input.taskType.toLowerCase(),
   415|  );
   416|  if (isProhibited) {
   417|    return { ok: false, taskId: null, error: `Task type "${input.taskType}" is prohibited for agent ${input.agentId}`, deduplicated: false };
   418|  }
   419|
   420|  // Dedup check
   421|  if (input.dedupKey) {
   422|    let dedupSet = dedupRegistry.get(input.agentId);
   423|    if (!dedupSet) {
   424|      dedupSet = new Set();
   425|      dedupRegistry.set(input.agentId, dedupSet);
   426|    }
   427|    if (dedupSet.has(input.dedupKey)) {
   428|      return { ok: true, taskId: null, error: null, deduplicated: true };
   429|    }
   430|    dedupSet.add(input.dedupKey);
   431|  }
   432|
   433|  const taskId = `task-${input.agentId}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
   434|  const task: AgentTask = {
   435|    taskId,
   436|    agentId: input.agentId,
   437|    taskType: input.taskType,
   438|    payload: input.payload,
   439|    priority: input.priority ?? 'medium',
   440|    status: 'queued',
   441|    requestingAgentId: input.requestingAgentId ?? null,
   442|    ownerApprovalToken: input.ownerApprovalToken ?? null,
   443|    createdAt: new Date().toISOString(),
   444|    leasedAt: null,
   445|    completedAt: null,
   446|    dedupKey: input.dedupKey ?? null,
   447|  };
   448|
   449|  const inbox = getOrCreateInbox(input.agentId);
   450|  inbox.push(task);
   451|
   452|  // Update queue depth
   453|  const st = executionStates.get(input.agentId);
   454|  if (st) st.queueDepth = inbox.filter((t) => t.status === 'queued').length;
   455|
   456|  return { ok: true, taskId, error: null, deduplicated: false };
   457|}
   458|
   459|/**
   460| * Lease the next task for an agent. Agent A cannot consume Agent B's task.
   461| */
   462|export function leaseNextTask(agentId: string, workerId: string): { ok: boolean; task: AgentTask | null; error: string | null } {
   463|  const state = executionStates.get(agentId);
   464|  if (!state) return { ok: false, task: null, error: `Unknown agent: ${agentId}` };
   465|  if (state.disabledState) return { ok: false, task: null, error: `Agent ${agentId} is disabled` };
   466|  if (state.pauseState) return { ok: false, task: null, error: `Agent ${agentId} is paused — receives no new execution` };
   467|  if (state.activeTaskId) return { ok: false, task: null, error: `Agent ${agentId} already has active task ${state.activeTaskId}` };
   468|
   469|  const inbox = taskInboxes.get(agentId);
   470|  if (!inbox || inbox.length === 0) return { ok: true, task: null, error: null };
   471|
   472|  // Sort by priority then creation time
   473|  const priorityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
   474|  const queued = inbox.filter((t) => t.status === 'queued').sort((a, b) => {
   475|    const pDiff = priorityOrder[a.priority] - priorityOrder[b.priority];
   476|    if (pDiff !== 0) return pDiff;
   477|    return a.createdAt.localeCompare(b.createdAt);
   478|  });
   479|
   480|  if (queued.length === 0) return { ok: true, task: null, error: null };
   481|
   482|  const task = queued[0];
   483|  task.status = 'leased';
   484|  task.leasedAt = new Date().toISOString();
   485|  state.activeTaskId = task.taskId;
   486|  state.availability = 'busy';
   487|  state.queueDepth = inbox.filter((t) => t.status === 'queued').length;
   488|
   489|  return { ok: true, task, error: null };
   490|}
   491|
   492|/**
   493| * Complete a task — updates execution state and records evidence.
   494| */
   495|export function completeTask(
   496|  agentId: string,
   497|  taskId: string,
   498|  result: { status: 'completed' | 'failed' | 'blocked'; error?: string },
   499|): { ok: boolean; error: string | null } {
   500|  const state = executionStates.get(agentId);
   501|  if (!state) return { ok: false, error: `Unknown agent: ${agentId}` };
   502|
   503|  const inbox = taskInboxes.get(agentId);
   504|  if (!inbox) return { ok: false, error: `No inbox for agent ${agentId}` };
   505|
   506|  const task = inbox.find((t) => t.taskId === taskId);
   507|  if (!task) return { ok: false, error: `Task ${taskId} not found in agent ${agentId} inbox` };
   508|  if (task.agentId !== agentId) return { ok: false, error: `Task ${taskId} does not belong to agent ${agentId}` };
   509|
   510|  task.status = result.status;
   511|  task.completedAt = new Date().toISOString();
   512|  state.activeTaskId = null;
   513|  state.availability = state.pauseState ? 'paused' : 'available';
   514|  state.totalRuns++;
   515|
   516|  if (result.status === 'completed') {
   517|    state.successfulRuns++;
   518|    state.lastSuccessfulRun = new Date().toISOString();
   519|    state.health = 'healthy';
   520|    state.errorState = null;
   521|    state.retryCount = 0;
   522|    state.evidenceCount++;
   523|  } else if (result.status === 'failed') {
   524|    state.failedRuns++;
   525|    state.lastFailedRun = new Date().toISOString();
   526|    state.health = 'degraded';
   527|    state.errorState = result.error ?? 'Unknown error';
   528|    state.retryCount++;
   529|  } else if (result.status === 'blocked') {
   530|    state.health = 'degraded';
   531|    state.errorState = result.error ?? 'Blocked';
   532|  }
   533|
   534|  return { ok: true, error: null };
   535|}
