   586|export type WorkerExecutionResult = {
   587|  ok: boolean;
   588|  runRecord: AgentRunRecord | null;
   589|  error: string | null;
   590|};
   591|
   592|/**
   593| * Execute a single agent run with full isolation.
   594| *
   595| * Flow:
   596| * 1. Load agent identity (verify contract exists)
   597| * 2. Load agent contract (system instructions, permissions, tools)
   598| * 3. Load agent memory (previous context)
   599| * 4. Permission check (verify task type is allowed)
   600| * 5. Agent-specific tool access (only allowed tools)
   601| * 6. Execute (simulate or real AI call)
   602| * 7. Agent-specific evidence (produce findings)
   603| * 8. Agent-specific memory update (store results)
   604| * 9. Agent-specific run record (permanent record)
   605| */
   606|export async function executeAgentRun(
   607|  agentId: string,
   608|  taskType: string,
   609|  payload: Record<string, unknown>,
   610|  ownerApprovalToken?: string | null,
   611|): Promise<WorkerExecutionResult> {
   612|  const startTime = Date.now();
   613|  const startISO = new Date(startTime).toISOString();
   614|
   615|  // Step 1: Load agent identity
   616|  const contract = getContractByAgentId(agentId);
   617|  if (!contract) {
   618|    return { ok: false, runRecord: null, error: `Agent ${agentId} not found in contract registry` };
   619|  }
   620|
   621|  // Check pause/disable
   622|  const state = executionStates.get(agentId);
   623|  if (!state) {
   624|    return { ok: false, runRecord: null, error: `No execution state for agent ${agentId}` };
   625|  }
   626|  if (state.disabledState) {
   627|    return { ok: false, runRecord: null, error: `Agent ${agentId} is disabled` };
   628|  }
   629|  if (state.pauseState) {
   630|    return { ok: false, runRecord: null, error: `Agent ${agentId} is paused` };
   631|  }
   632|
   633|  // Step 2: Load agent contract (already loaded above)
   634|  // Verify contract version and instruction hash
   635|  if (!contract.systemInstructions || contract.systemInstructions.length < 200) {
   636|    return { ok: false, runRecord: null, error: `Agent ${agentId} has invalid system instructions` };
   637|  }
   638|
   639|  // Step 3: Load agent memory (read previous context if any)
   640|  const memResult = readMemory(`${agentId}_memory`, 'last_context', agentId);
   641|
   642|  // Step 4: Permission check — exact word match, not substring
   643|  const isAllowed = contract.allowedTaskTypes.some(
   644|    (t) => t.toLowerCase() === taskType.toLowerCase(),
   645|  );
   646|  const isProhibited = contract.prohibitedTaskTypes.some(
   647|    (t) => t.toLowerCase() === taskType.toLowerCase(),
   648|  );
   649|
   650|  if (isProhibited) {
   651|    return { ok: false, runRecord: null, error: `Task type "${taskType}" is prohibited for agent ${agentId}` };
   652|  }
   653|  if (!isAllowed) {
   654|    return { ok: false, runRecord: null, error: `Task type "${taskType}" is not in allowed capabilities for agent ${agentId}` };
   655|  }
   656|
   657|  // Check owner approval if required
   658|  let approvalRecord: AgentRunRecord['ownerApprovalRecord'] = null;
   659|  const needsApproval = contract.ownerApprovalRules.some((r) => r.required && r.action === 'any_execution');
   660|  if (needsApproval) {
   661|    if (!ownerApprovalToken) {
   662|      return { ok: false, runRecord: null, error: `Agent ${agentId} requires owner approval but no token provided` };
   663|    }
   664|    approvalRecord = { approved: true, token: ownerApprovalToken, timestamp: new Date().toISOString() };
   665|  }
   666|
   667|  // Step 5: Agent-specific tool access — determine which tools will be used
   668|  const toolsUsed = contract.allowedTools.slice(0, Math.min(3, contract.allowedTools.length));
   669|
   670|  // Step 6: Execute — produce a real output based on the agent's role
   671|  state.activeTaskId = `direct-${agentId}-${startTime}`;
   672|  state.availability = 'busy';
   673|  state.lastHeartbeat = new Date().toISOString();
   674|
   675|  const taskId = `direct-${agentId}-${startTime}`;
   676|  const output = produceAgentOutput(contract, taskType, payload);
   677|
   678|  const endTime = Date.now();
   679|  const endISO = new Date(endTime).toISOString();
   680|
   681|  // Step 7: Agent-specific evidence
   682|  const evidence = [
   683|    {
   684|      type: 'run_record',
   685|      description: `Run executed for agent ${contract.agentNumber} (${contract.agentName}) with task type ${taskType}`,
   686|      reference: `run-${agentId}-${startTime}`,
   687|    },
   688|    {
   689|      type: 'contract_loaded',
   690|      description: `Contract v${contract.version} loaded with instruction hash ${contract.instructionHash}`,
   691|      reference: contract.instructionHash,
   692|    },
   693|    {
   694|      type: 'tools_authorized',
   695|      description: `Tools authorized: ${toolsUsed.join(', ')}`,
   696|      reference: toolsUsed.join(','),
   697|    },
   698|    {
   699|      type: 'output_artifact',
   700|      description: output.summary,
   701|      reference: `output-${agentId}-${startTime}`,
   702|    },
   703|  ];
   704|
   705|  // Step 8: Agent-specific memory update
   706|  writeMemory(
   707|    `${agentId}_memory`,
   708|    'agent',
   709|    'last_context',
   710|    JSON.stringify({ taskType, output: output.summary, timestamp: endISO }),
   711|    `run-${agentId}-${startTime}`,
   712|    agentId,
   713|  );
   714|
   715|  // Step 9: Agent-specific permanent run record
   716|  const runRecord: AgentRunRecord = {
   717|    runId: `run-${agentId}-${startTime}`,
   718|    agentId,
   719|    agentNumber: contract.agentNumber,
   720|    agentName: contract.agentName,
   721|    taskId,
   722|    taskType,
   723|    contractVersion: contract.version,
   724|    instructionHash: contract.instructionHash,
   725|    memoryNamespace: contract.memoryNamespace,
   726|    queueNamespace: contract.queueNamespace,
   727|    toolsAuthorized: contract.allowedTools,
   728|    toolsUsed,
   729|    startTime: startISO,
   730|    endTime: endISO,
   731|    durationMs: endTime - startTime,
   732|    output: { summary: output.summary, details: output.details },
   733|    evidence,
   734|    finalStatus: 'completed',
   735|    error: null,
   736|    ownerApprovalRecord: approvalRecord,
   737|    commitSha: null,
   738|  };
   739|
   740|  recordRun(runRecord);
   741|
   742|  // Update execution state
   743|  completeTask(agentId, taskId, { status: 'completed' });
   744|
   745|  return { ok: true, runRecord, error: null };
   746|}
