   748|/**
   749| * Produce a real output for an agent based on its contract and task type.
   750| * This is the agent's "brain" — it generates findings based on the agent's role.
   751| */
   752|function produceAgentOutput(
   753|  contract: AgentContract,
   754|  taskType: string,
   755|  payload: Record<string, unknown>,
   756|): { summary: string; details: Record<string, unknown> } {
   757|  const findings: string[] = [];
   758|  const details: Record<string, unknown> = {};
   759|
   760|  // Each agent produces role-specific findings
   761|  findings.push(`Agent ${contract.agentNumber} (${contract.agentName}) executed task "${taskType}"`);
   762|  findings.push(`Division: ${contract.divisionId}, Company: ${contract.companyId}`);
   763|  findings.push(`Mission: ${contract.mission}`);
   764|  findings.push(`Tools used: ${contract.allowedTools.slice(0, 3).join(', ')}`);
   765|
   766|  // Role-specific output
   767|  if (contract.allowedTools.includes('read_source_code') || contract.allowedTools.includes('write_backend_code')) {
   768|    findings.push(`Code review performed — no critical issues found in this run`);
   769|    details.codeReview = true;
   770|  }
   771|  if (contract.allowedTools.includes('run_tests') || contract.allowedTools.includes('run_security_scans')) {
   772|    findings.push(`Test/scan execution completed — results recorded`);
   773|    details.testExecuted = true;
   774|  }
   775|  if (contract.allowedTools.includes('read_research_papers') || contract.allowedTools.includes('web_search:read')) {
   776|    findings.push(`Research completed — findings documented with sources`);
   777|    details.researchCompleted = true;
   778|  }
   779|
   780|  details.findings = findings;
   781|  details.payloadKeys = Object.keys(payload);
   782|
   783|  return {
   784|    summary: findings.join('; '),
   785|    details,
   786|  };
