   959|// ── Failure Isolation Test ──────────────────────────────────────────────────
   960|
   961|export function testFailureIsolation(): {
   962|  tested: number;
   963|  passed: number;
   964|  failed: number;
   965|  results: Array<{ agentId: string; scenario: string; isolated: boolean; reason: string }>;
   966|} {
   967|  const results: Array<{ agentId: string; scenario: string; isolated: boolean; reason: string }> = [];
   968|  const testAgents = ALL_AGENT_CONTRACTS.slice(0, 10); // Test first 10 as representative
   969|
   970|  for (const contract of testAgents) {
   971|    // Simulate failure for this agent
   972|    const state = executionStates.get(contract.agentId)!;
   973|    const originalHealth = state.health;
   974|    state.health = 'failed';
   975|    state.errorState = 'Simulated failure for isolation test';
   976|
   977|    // Check that other agents are unaffected
   978|    let isolated = true;
   979|    let reason = 'Failure isolated — other agents unaffected';
   980|    for (const other of ALL_AGENT_CONTRACTS) {
   981|      if (other.agentId === contract.agentId) continue;
   982|      const otherState = executionStates.get(other.agentId);
   983|      if (otherState && otherState.health === 'failed' && otherState.errorState === state.errorState) {
   984|        isolated = false;
   985|        reason = `Failure leaked to agent ${other.agentId}`;
   986|        break;
   987|      }
   988|    }
   989|
   990|    results.push({
   991|      agentId: contract.agentId,
   992|      scenario: 'simulated_failure',
   993|      isolated,
   994|      reason,
   995|    });
   996|
   997|    // Restore original state
   998|    state.health = originalHealth;
   999|    state.errorState = null;
  1000|  }
  1001|
  1002|  return {
  1003|    tested: testAgents.length,
  1004|    passed: results.filter((r) => r.isolated).length,
