{"filePath": "expo/app/ivx/real-execution-112.tsx", "content": "import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ActivityIndicator, RefreshControl, ScrollView, StyleSheet, Text, TouchableOpacity, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Stack, useRouter } from 'expo-router';
import { Activity, AlertTriangle, ArrowLeft, BadgeCheck, Database, RefreshCw, ShieldCheck, Wrench } from 'lucide-react-native';

const API_BASE = (process.env.EXPO_PUBLIC_IVX_API_BASE_URL || 'https://api.ivxholding.com').replace(/\/+$/, '');
const STATUS_URL = `${API_BASE}/api/ivx/agents/real-status`;
const POLL_INTERVAL_MS = 6_000;

type AgentRow = {
  agentId: string;
  agentNumber: number;
  name: string;
  division: string;
  status: 'running' | 'blocked' | 'failed' | 'completed' | 'idle';
  health: string;
  lastRealTool: string | null;
  lastSource: string | null;
  lastEvidenceSha: string | null;
  lastHeartbeat: string | null;
  heartbeatStale: boolean;
  lastDurationMs: number;
  lastError: string | null;
  retryCount: number;
  costUsd: number;
  totalRuns: number;
  successfulRuns: number;
  failedRuns: number;
};

type AlertRowT = {
  id: string;
  alert_type: string;
  agent_id: string | null;
  severity: string;
  detail: string | null;
  created_at: string;
};

type CertificateT = {
  certificate_id: string;
  passed: boolean;
  total_agents: number;
  healthy: number;
  real_execution_verified: number;
  evidence_verified: number;
  persistence_verified: boolean;
  simulated_runs: number;
  commit_sha: string | null;
  runtime_version: string;
  certified_at: string;
} | null;

type ActiveRunT = {
  runId: string;
  status: string;
  processed: number;
  total: number;
  failed: number;
  currentAgent: string | null;
  phase: string;
  note: string;
} | null;

type RealStatus = {
  ok: boolean;
  persistence?: { configured: boolean; tablesReady: boolean; detail: string };
  totalAgents: number;
  running: number;
  blocked: number;
  failed: number;
  completed: number;
  staleHeartbeats: number;
  totalCostUsd: number;
  agents: AgentRow[];
  alerts: AlertRowT[];
  latestCertificate: CertificateT;
  activeRun: ActiveRunT;
};

const STATUS_COLORS: Record<AgentRow['status'], string> = {
  running: '#38bdf8',
  blocked: '#f59e0b',
  failed: '#ef4444',
  completed: '#22c55e',
  idle: '#64748b',
};

function timeAgo(iso: string | null): string {
  if (!iso) return 'never';
  const ms = Date.now() - new Date(iso).getTime();
  if (Number.isNaN(ms)) return 'unknown';
  if (ms < 60_000) return `${Math.max(1, Math.round(ms / 1000))}s ago`;
  if (ms < 3_600_000) return `${Math.round(ms / 60_000)}m ago`;
  return `${Math.round(ms / 3_600_000)}h ago`;
}

function truncate(value: string | null, max: number): string {
  if (!value) return '—';
  return value.length > max ? `${value.slice(0, max)}…` : value;
}

export default function RealExecution112Screen() {
  const router = useRouter();
  const [data, setData] = useState<RealStatus | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState<boolean>(false);
  const [filter, setFilter] = useState<'all' | AgentRow['status']>('all');
  const mounted = useRef<boolean>(true);

  const load = useCallback(async (): Promise<void> => {
    try {
      const res = await fetch(STATUS_URL, { headers: { Accept: 'application/json' } });
      const json = (await res.json()) as RealStatus;
      if (mounted.current) {
        setData(json);
        setError(null);
      }
    } catch (err) {
      if (mounted.current) setError(err instanceof Error ? err.message : 'network error');
    }
  }, []);

  useEffect(() => {
    mounted.current = true;
    void load();
    const timer = setInterval(() => { void load(); }, POLL_INTERVAL_MS);
    return () => {
      mounted.current = false;
      clearInterval(timer);
    };
  }, [load]);

  const onRefresh = useCallback(async (): Promise<void> => {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  }, [load]);

